<script setup lang="ts">
import { computed, ref } from 'vue'
import { UploadFilled, FolderOpened, Document, Delete, Refresh } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { service } from '@/services/service'
import type { Material, UploadEntry } from '@/domain/types'
import { formatSize, messageOf } from '@/composables/useFileBrowser'
import { uploadPath, uploadFileIssue, summarizeUploadTypes } from '@/domain/uploadFiles'
const props=defineProps<{modelValue:boolean;folderId?:string;space:string;path:string}>()
const emit=defineEmits<{'update:modelValue':[boolean];uploaded:[Material[]]}>()
type QueueEntry=UploadEntry&{key:string;selected:boolean;issue:string}
const filesInput=ref<HTMLInputElement>(),folderInput=ref<HTMLInputElement>(),queue=ref<QueueEntry[]>([]),uploading=ref(false),dragOver=ref(false),page=ref(1),filter=ref('all'),abortAfterCurrent=ref(false)
const types=computed(()=>summarizeUploadTypes(queue.value.map(item=>({path:item.relativePath,size:item.file.size}))))
const filtered=computed(()=>queue.value.filter(item=>filter.value==='all'||item.file.name.split('.').pop()?.toLowerCase()===filter.value))
const shown=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
const pending=computed(()=>queue.value.filter(item=>item.selected&&!item.issue&&['pending','failed'].includes(item.status)))
const selectedCount=computed(()=>queue.value.filter(item=>item.selected&&!item.issue).length)
const selectedSize=computed(()=>queue.value.filter(item=>item.selected&&!item.issue).reduce((sum,item)=>sum+item.file.size,0))
const pageAll=computed(()=>shown.value.filter(item=>!item.issue&&item.status!=='uploaded').length>0&&shown.value.filter(item=>!item.issue&&item.status!=='uploaded').every(item=>item.selected))
const completed=computed(()=>queue.value.filter(item=>item.status==='uploaded').length)
function addFiles(files:File[]){if(uploading.value)return;const existing=new Set(queue.value.map(item=>`${item.relativePath}:${item.file.size}:${item.file.lastModified}`));for(const file of files){const path=uploadPath(file.webkitRelativePath,file.name),key=`${path}:${file.size}:${file.lastModified}`;if(existing.has(key))continue;existing.add(key);const issue=uploadFileIssue(path,file.size)||(queue.value.some(item=>item.relativePath===path)?'同一路径文件已在清单中，请先移除旧文件':'');queue.value.push({file,relativePath:path,key,selected:!issue&&!/\.(zip|rar|7z|exe|msi|tmp|bat|sh)$/i.test(path),issue,status:'pending'})}page.value=1}
function choose(event:Event){const input=event.target as HTMLInputElement;addFiles(Array.from(input.files||[]));input.value=''}
function selectPage(value:boolean){for(const item of shown.value)if(!item.issue&&item.status!=='uploaded')item.selected=value}
function documentsOnly(){for(const item of queue.value)if(!item.issue&&item.status!=='uploaded')item.selected=/\.(pdf|doc|docx|xls|xlsx|csv|txt|md|json|png|jpg|jpeg)$/i.test(item.relativePath)}
async function upload(){if(!pending.value.length)return;if(!props.folderId){ElMessage.warning('请先在资料管理中选择上传目录。');return}uploading.value=true;abortAfterCurrent.value=false;const targetFolder=props.folderId!,targetSpace=props.space;const saved:Material[]=[];try{await service.listFolders(targetSpace);const batch=[...pending.value];for(const item of batch){if(abortAfterCurrent.value)break;item.status='uploading';item.error='';try{const result=await service.upload(item.file,targetFolder,item.relativePath);item.id=result.id;item.status='uploaded';saved.push(result)}catch(e){item.status='failed';item.error=messageOf(e)}}if(saved.length){emit('uploaded',saved);ElMessage.success(`已上传 ${saved.length} 份文件`)} }catch(e){ElMessage.error(messageOf(e))}finally{uploading.value=false}}
async function close(){if(uploading.value){try{await ElMessageBox.confirm('正在上传。关闭后将继续处理当前文件，随后暂停剩余文件。','暂停上传',{confirmButtonText:'暂停并关闭',cancelButtonText:'继续上传'});abortAfterCurrent.value=true}catch{return}}emit('update:modelValue',false)}
</script>
<template><el-dialog :model-value="modelValue" title="上传资料" width="min(1020px, calc(100vw - 28px))" :close-on-click-modal="false" :before-close="close" @update:model-value="emit('update:modelValue',$event)"><div class="upload-target"><span>上传到</span><strong>{{path}}</strong></div><input ref="filesInput" type="file" multiple hidden @change="choose"/><input ref="folderInput" type="file" webkitdirectory multiple hidden @change="choose"/><div :class="['upload-drop',{'drag-active':dragOver}]" @dragover.prevent="dragOver=true" @dragleave="dragOver=false" @drop.prevent="dragOver=false;addFiles(Array.from($event.dataTransfer?.files||[]))"><el-icon class="upload-icon" :size="36"><UploadFilled/></el-icon><div><strong>拖入文件，或选择要上传的资料</strong><p>单文件不超过 100 MB；文件夹上传保留原目录层级。</p><div class="upload-choices"><el-button :icon="Document" :disabled="uploading" @click="filesInput?.click()">选择文件</el-button><el-button :icon="FolderOpened" :disabled="uploading" @click="folderInput?.click()">选择文件夹</el-button></div></div></div><template v-if="queue.length"><div class="upload-toolbar"><span>待上传清单 <strong>{{queue.length}}</strong> 份</span><el-select v-model="filter" aria-label="筛选上传类型" @change="page=1"><el-option value="all" label="全部类型"/><el-option v-for="type in types" :key="type.extension" :value="type.extension" :label="`${type.extension.toUpperCase()} · ${type.count} 份`"/></el-select><el-button :disabled="uploading" @click="documentsOnly">仅选择文档</el-button><el-button :disabled="uploading" @click="queue=queue.filter(item=>item.status==='uploaded')">清空待上传</el-button></div><el-table :data="shown" max-height="310" row-key="key"><el-table-column width="80"><template #header><el-checkbox :model-value="pageAll" :disabled="uploading" aria-label="选择本页上传文件" @change="selectPage(Boolean($event))">本页</el-checkbox></template><template #default="{row}"><el-checkbox v-model="row.selected" :aria-label="`上传 ${row.file.name}`" :disabled="uploading||!!row.issue||row.status==='uploaded'"/></template></el-table-column><el-table-column label="文件名称 / 目录" min-width="300"><template #default="{row}"><div>{{row.file.name}}</div><small class="upload-relative">{{row.relativePath}}</small></template></el-table-column><el-table-column label="大小" width="105"><template #default="{row}">{{formatSize(row.file.size)}}</template></el-table-column><el-table-column label="状态" min-width="180"><template #default="{row}"><span :class="['upload-status',row.status]">{{row.issue||row.error||{pending:'等待上传',uploading:'上传中',uploaded:'上传完成',failed:'上传失败'}[row.status as string]}}</span></template></el-table-column><el-table-column width="50"><template #default="{row}"><el-button text :icon="Delete" :disabled="uploading||row.status==='uploaded'" :aria-label="`移除 ${row.file.name}`" @click="queue=queue.filter(item=>item.key!==row.key)"/></template></el-table-column></el-table><div class="upload-summary"><span>已选 <strong>{{selectedCount}}</strong> 份 · {{formatSize(selectedSize)}}<span v-if="completed"> · 已上传 {{completed}} 份</span></span><el-pagination v-model:current-page="page" :page-size="20" :total="filtered.length" layout="prev,pager,next"/></div><el-progress v-if="uploading||completed" :percentage="Math.round(completed/queue.length*100)" :stroke-width="5" :show-text="false"/></template><template #footer><el-button @click="close">{{uploading?'暂停并关闭':'关闭'}}</el-button><el-button type="primary" :loading="uploading" :disabled="!pending.length||!folderId" @click="upload">{{queue.some(item=>item.status==='failed')?'上传 / 重试失败文件':'开始上传'}}{{pending.length?`（${pending.length}）`:''}}</el-button></template></el-dialog></template>
<style scoped>.upload-target{display:flex;gap:12px;margin-bottom:16px;color:#596b80;font-size:14px}.upload-target strong{color:#1e3046;font-weight:500;overflow-wrap:anywhere}.upload-drop{display:flex;gap:20px;justify-content:center;align-items:center;padding:22px;border:1px dashed #a8bfe8;border-radius:9px;background:#f7faff}.upload-drop.drag-active{border-color:#3269db;background:#eef4ff}.upload-icon{color:#3269db}.upload-drop strong{font-size:16px}.upload-drop p{font-size:14px;color:#596b80;margin:8px 0 14px}.upload-choices{display:flex;gap:8px}.upload-choices .el-button+.el-button{margin-left:0}.upload-toolbar{display:flex;align-items:center;gap:10px;padding:16px 0 12px;flex-wrap:wrap}.upload-toolbar>span{margin-right:auto}.upload-toolbar .el-select{width:170px}.upload-relative{display:block;color:#596b80;font-size:14px;overflow-wrap:anywhere}.upload-status{font-size:14px;overflow-wrap:anywhere}.upload-status.failed{color:#a33e3e}.upload-status.uploaded{color:#1d735b}.upload-summary{display:flex;align-items:center;justify-content:space-between;padding:12px 0;font-size:14px;color:#596b80;gap:10px}.upload-summary strong{font-size:17px;color:#2555b4}.upload-summary .el-pagination{max-width:70%;overflow-x:auto}@media(max-width:600px){.upload-drop{padding:18px;gap:12px}.upload-icon{display:none}.upload-toolbar .el-select{width:130px}.upload-summary{flex-wrap:wrap}}</style>
